'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { Receipt, Mail, Lock, User, AlertCircle } from 'lucide-react';
import { Button, Input } from '@/components/ui/base';

export default function RegisterPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  
  const [data, setData] = useState({
      name: '',
      email: '',
      password: '',
      confirmPassword: ''
  });

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (data.password !== data.confirmPassword) {
        setError('Passwords do not match');
        setLoading(false);
        return;
    }

    try {
        const response = await fetch('/api/register', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                name: data.name,
                email: data.email,
                password: data.password
            })
        });

        if (response.ok) {
            router.push('/login');
        } else {
            const res = await response.json();
            setError(res.error || 'Registration failed');
        }
    } catch (err) {
        setError('Something went wrong');
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-gray-50">
      <div className="w-full max-w-md bg-white p-8 rounded-2xl shadow-xl">
        <div className="text-center mb-8">
          <div className="flex justify-center mb-4">
             <div className="bg-green-500 p-2 rounded">
              <Receipt className="h-8 w-8 text-white" />
            </div>
          </div>
          <h2 className="text-3xl font-bold text-gray-900">Create an account</h2>
          <p className="mt-2 text-gray-500">Start your financial journey with Finora</p>
        </div>

        {error && (
            <div className="bg-red-50 text-red-500 p-3 rounded-md mb-4 flex items-center gap-2 text-sm">
                <AlertCircle size={16} />
                {error}
            </div>
        )}

        <form onSubmit={handleRegister} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Full Name</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <User className="h-5 w-5 text-gray-400" />
              </div>
              <Input 
                value={data.name}
                onChange={(e: any) => setData({...data, name: e.target.value})}
                placeholder="John Doe" 
                className="pl-10 h-11" 
                required 
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Email address</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Mail className="h-5 w-5 text-gray-400" />
              </div>
              <Input 
                type="email" 
                value={data.email}
                onChange={(e: any) => setData({...data, email: e.target.value})}
                placeholder="you@example.com" 
                className="pl-10 h-11" 
                required 
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Lock className="h-5 w-5 text-gray-400" />
              </div>
              <Input 
                type="password" 
                value={data.password}
                onChange={(e: any) => setData({...data, password: e.target.value})}
                placeholder="Create a password" 
                className="pl-10 h-11" 
                required 
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Confirm Password</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Lock className="h-5 w-5 text-gray-400" />
              </div>
              <Input 
                type="password" 
                value={data.confirmPassword}
                onChange={(e: any) => setData({...data, confirmPassword: e.target.value})}
                placeholder="Confirm password" 
                className="pl-10 h-11" 
                required 
              />
            </div>
          </div>

          <Button 
            disabled={loading}
            className={`w-full h-12 text-base bg-green-600 hover:bg-green-700 flex justify-center items-center gap-2 ${loading ? 'opacity-70 cursor-not-allowed' : ''}`}
          >
            {loading ? 'Creating Account...' : 'Sign Up'}
          </Button>
        </form>

        <p className="mt-6 text-center text-sm text-gray-500">
          Already have an account?{' '}
          <Link href="/login" className="text-green-600 font-medium hover:text-green-500">
            Sign in
          </Link>
        </p>
      </div>
    </div>
  );
}
